examples.snippet:
.cv-scrim { position: fixed; inset: 0; z-index: var(--z-modal); display: flex; align-items: center; justify-content: center; background: var(--bg-scrim); }
.cv-scrim[hidden] { display: none; }
#overlay-root > .cv-scrim.cv-scrim-through { pointer-events: none; background: transparent; backdrop-filter: none; -webkit-backdrop-filter: none; }
.cv-scrim.cv-scrim-through .cv-dialog { pointer-events: auto; }
